insert into public.stations (id, name, lines, lat, lon, neighborhood, story) values
  ('place-bucen', 'Boston University Central', array['Green-B']::text[], 42.350082, -71.106865, 'Fenway-Kenmore', 'The B branch stops on Commonwealth Avenue beside Marsh Chapel. Head behind the chapel and the campus opens toward the Charles River.'),
  ('place-kencl', 'Kenmore', array['Green-B', 'Green-C', 'Green-D']::text[], 42.348949, -71.095169, 'Fenway-Kenmore', 'Three Green Line branches meet here. The Citgo sign marks the square, and the streets south of it lead to Fenway Park.'),
  ('place-coecl', 'Copley', array['Green-B', 'Green-C', 'Green-D', 'Green-E']::text[], 42.349974, -71.077447, 'Back Bay', 'Come out onto Boylston Street between the Central Library and Copley Square, with Newbury Street and the Commonwealth Avenue Mall a few blocks away.'),
  ('place-pktrm', 'Park Street', array['Red', 'Green-B', 'Green-C', 'Green-D', 'Green-E']::text[], 42.3563946, -71.0624242, 'Downtown', 'The Red and Green lines meet at the corner of Boston Common. Start on Tremont Street or cut through the Common toward the Public Garden.'),
  ('place-gover', 'Government Center', array['Blue', 'Green-B', 'Green-C', 'Green-D', 'Green-E']::text[], 42.359705, -71.059215, 'Downtown', 'The Blue and Green lines meet next to City Hall Plaza. Walk downhill toward Faneuil Hall and the market buildings.'),
  ('place-haecl', 'Haymarket', array['Orange', 'Green-D', 'Green-E']::text[], 42.363021, -71.05829, 'North End / Downtown', 'Step out near Boston Public Market and cross the Greenway to reach the North End. You can go from a market snack to North Square in one short walk.'),
  ('place-harsq', 'Harvard', array['Red']::text[], 42.373362, -71.118956, 'Harvard Square', 'Step out into Harvard Square, where Massachusetts Avenue meets the brick gates of Harvard Yard. Independent shops and university museums are a short walk away.'),
  ('place-cntsq', 'Central', array['Red']::text[], 42.365486, -71.103802, 'Central Square', 'Central puts you on Massachusetts Avenue between Cambridgeport and The Port. Look for murals along Mass Ave or detour down Pearl Street.'),
  ('place-chncl', 'Chinatown', array['Orange']::text[], 42.352547, -71.062752, 'Chinatown', 'Leave the Orange Line at Washington and Boylston. Follow the neighborhood streets toward the Beach Street gate and the southern end of the Greenway.')
insert into public.quests (id, station_id, type, title, description, lat, lon, price_tier, vibe_tags, hours, photo_url, xp, checkin_radius_m, duration_min, walk_min) values
  ('marsh-plaza-details', 'place-bucen', 'scenic', 'Marsh Plaza Details', 'From the plaza, find two different shapes in the stonework on Marsh Chapel’s front. Pick the detail you’d put on a passport stamp. Best in daylight.', 42.35028, -71.10696, 0, array['architecture', 'campus', 'photo']::text[], 'always', 'https://upload.wikimedia.org/wikipedia/commons/5/52/Marsh_Chapel.jpg', 50, 75, 10, 2),
  ('bu-beach-river-view', 'place-bucen', 'scenic', 'BU Beach River View', 'Walk behind Marsh Chapel to BU Beach. Find a public spot with a view toward the Charles and pick your favorite angle. Best in daylight.', 42.35077, -71.10699, 0, array['river', 'quiet', 'photo']::text[], 'always', null, 50, 75, 15, 3),
  ('pavement-bu-bagel', 'place-bucen', 'food', 'Pavement Bagel Break', 'At Pavement across from Marsh Chapel, pick a bagel or coffee from the counter menu and share your go-to combo.', 42.34998, -71.10704, 1, array['bagel', 'coffee']::text[], '07:00-19:00', null, 60, 75, 15, 2),
  ('kenmore-citgo-angle', 'place-kencl', 'scenic', 'Kenmore Sign Hunt', 'From the public sidewalk in Kenmore Square, find a spot where the Citgo sign and the streetscape fit in the same photo. Best in daylight.', 42.34894, -71.09544, 0, array['photo', 'architecture', 'outdoors']::text[], 'always', null, 50, 75, 10, 2),
  ('fenway-scoreboard-street', 'place-kencl', 'scenic', 'Fenway From the Sidewalk', 'Walk to the corner of Jersey Street and Brookline Avenue and find a Fenway Park sign you’d use to introduce Boston to a friend. Street access can change on game days.', 42.34686, -71.09755, 0, array['sports', 'photo', 'architecture']::text[], 'always', 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Outside_Fenway_Park_in_Boston.jpg', 50, 75, 15, 5),
  ('tatte-fenway-pastry', 'place-kencl', 'food', 'Fenway Pastry Pick', 'At Tatte on Boylston, choose a pastry from the case and note which one you’d tell a friend to try.', 42.34457, -71.09755, 1, array['pastry', 'coffee']::text[], 'Mon-Sat 07:00-20:00; Sun 07:30-19:00', null, 60, 75, 20, 8),
  ('copley-courtyard', 'place-coecl', 'scenic', 'Find the Library Courtyard', 'Enter the Central Library and find the courtyard. Look for an arch that frames the courtyard and choose your favorite viewpoint.', 42.34943, -71.0781, 0, array['quiet', 'architecture', 'indoors']::text[], 'Mon-Thu 09:00-20:00; Fri,Sat 09:00-17:00; Sun 11:00-17:00', 'https://upload.wikimedia.org/wikipedia/commons/5/50/Boston_Public_Library_Courtyard.png', 50, 75, 25, 3),
  ('copley-mall-walk', 'place-coecl', 'scenic', 'Commonwealth Ave Mall Walk', 'Start on the tree-lined mall at Dartmouth Street. Walk one block and find a detail you’d normally miss from the sidewalk.', 42.35227, -71.07717, 0, array['walk', 'architecture', 'outdoors']::text[], 'always', null, 50, 75, 20, 6),
  ('thinking-cup-newbury', 'place-coecl', 'food', 'Newbury Coffee Break', 'Stop at Thinking Cup on Newbury Street and pick a coffee, tea, or small pastry that fits your budget.', 42.35189, -71.07557, 1, array['coffee', 'pastry']::text[], 'Mon-Thu 07:00-19:00; Fri-Sun 07:00-21:00', null, 60, 75, 20, 7),
  ('frog-pond-lookout', 'place-pktrm', 'scenic', 'Frog Pond Lookout', 'Find Frog Pond in Boston Common and look back across the park from the pond edge. Check in from the path.', 42.3564, -71.06542, 0, array['park', 'photo', 'outdoors']::text[], '06:30-23:00', null, 50, 75, 15, 5),
  ('public-garden-lagoon', 'place-pktrm', 'scenic', 'Frame the Lagoon', 'Walk to the Public Garden footbridge and find a view that fits both the lagoon and the Back Bay skyline.', 42.35403, -71.0695, 0, array['park', 'water', 'photo']::text[], 'always', null, 50, 75, 20, 10),
  ('thinking-cup-common', 'place-pktrm', 'food', 'Coffee by the Common', 'At Thinking Cup on Tremont Street, pick up a coffee or tea and find a spot overlooking Boston Common.', 42.35466, -71.06336, 1, array['coffee', 'takeout']::text[], '07:00-19:00', null, 60, 75, 15, 4),
  ('city-hall-plaza-shapes', 'place-gover', 'scenic', 'City Hall Plaza Shapes', 'From the plaza, choose a spot where you can see the contrast between the brick ground and City Hall’s concrete facade. Parts of the plaza can close for events.', 42.36056, -71.05939, 0, array['architecture', 'photo', 'outdoors']::text[], 'always', null, 50, 75, 10, 2),
  ('faneuil-hall-exterior', 'place-gover', 'scenic', 'Spot the Faneuil Hall Weathervane', 'From the outdoor plaza, look up and find the grasshopper weather vane. Share one detail you noticed on the building. Best in daylight.', 42.36003, -71.05694, 0, array['history', 'architecture', 'photo']::text[], 'always', 'https://upload.wikimedia.org/wikipedia/commons/4/4b/Faneuil_Hall%2C_Boston%2C_exterior.jpg', 50, 75, 10, 5),
  ('quincy-market-snack', 'place-gover', 'food', 'Quincy Market Snack Mission', 'Walk the food colonnade and choose one counter snack. Compare the posted prices before you order. Vendors keep their own hours.', 42.36013, -71.05559, 2, array['market', 'snack', 'indoors']::text[], 'Mon-Sat 10:00-21:00; Sun 11:00-19:00', null, 60, 75, 25, 6),
  ('public-market-local-snack', 'place-haecl', 'food', 'Find a New England Snack', 'At Boston Public Market, read two vendor signs and choose a small snack from a New England maker. Vendors keep their own hours.', 42.36188, -71.05728, 1, array['market', 'snack', 'indoors']::text[], 'Sun-Tue 08:00-18:00; Wed-Sat 08:00-20:00', null, 60, 75, 20, 3),
  ('north-end-greenway', 'place-haecl', 'scenic', 'Greenway to the North End', 'Cross to the North End Parks and find a bench or a view along the Greenway. Pick a meeting spot you’d send to a friend. Best in daylight.', 42.36345, -71.05497, 0, array['park', 'walk', 'outdoors']::text[], 'always', null, 50, 75, 15, 6),
  ('paul-revere-house', 'place-haecl', 'event', 'Step Inside the Paul Revere House', 'Do a self-guided museum visit and find a detail that tells you how a Boston household used the space. Open until 5:15 PM from mid-April through October.', 42.36374, -71.05369, 1, array['history', 'museum', 'indoors']::text[], '10:00-16:15', null, 80, 75, 40, 8),
  ('harvard-yard-gate', 'place-harsq', 'scenic', 'Find Johnston Gate', 'From the public sidewalk on Massachusetts Avenue, look for the brick and iron details of Harvard Yard’s Johnston Gate. Best in daylight.', 42.37419, -71.11873, 0, array['architecture', 'history', 'outdoors']::text[], 'always', null, 50, 75, 10, 3),
  ('harvard-art-courtyard', 'place-harsq', 'event', 'Look Up at the Art Museums', 'Visit the Harvard Art Museums on Quincy Street. From the courtyard, look up at the glass roof, then pick one artwork you’d come back to see.', 42.37423, -71.11415, 0, array['museum', 'art', 'indoors']::text[], 'Tue-Sun 10:00-17:00', null, 80, 75, 45, 7),
  ('harvard-tatte-pastry', 'place-harsq', 'food', 'Harvard Square Pastry Pick', 'Visit Tatte at 1288 Massachusetts Avenue and choose the pastry you’d recommend to a friend.', 42.37257, -71.11696, 1, array['pastry', 'coffee', 'indoors']::text[], 'Mon,Tue,Thu-Sat 07:00-20:30; Wed 07:00-19:00; Sun 07:30-19:00', null, 60, 75, 20, 4),
  ('central-graffiti-alley', 'place-cntsq', 'scenic', 'Catch Graffiti Alley in Color', 'Find the alley at 565–567 Massachusetts Avenue. Choose a color that ties together two pieces on the walls. Best in daylight.', 42.3642, -71.1015, 0, array['street-art', 'photo', 'outdoors']::text[], 'always', null, 50, 75, 10, 4),
  ('central-library-shelf', 'place-cntsq', 'event', 'Browse a Central Square Shelf', 'Stop at the Central Square Branch at 45 Pearl Street. Find a book whose title would make a good name for a T quest.', 42.3647, -71.10385, 0, array['books', 'quiet', 'indoors']::text[], 'Mon,Fri 10:00-18:00; Tue-Thu 10:00-21:00; Sat 10:00-14:00', null, 80, 75, 20, 3),
  ('central-1369-coffee', 'place-cntsq', 'food', 'Coffee at 1369', 'Visit 1369 Coffee House at 757 Massachusetts Avenue and pick a coffee or tea you’d order again.', 42.36638, -71.10519, 1, array['coffee', 'cozy', 'indoors']::text[], 'Mon-Fri 07:00-15:00; Sat,Sun 08:00-16:00', null, 60, 75, 15, 4),
  ('chinatown-gate-details', 'place-chncl', 'scenic', 'Look Up at Chinatown Gate', 'From the sidewalk at the Beach Street gate, look for the roof colors and decorative details above the entrance. Best in daylight.', 42.35109, -71.05864, 0, array['architecture', 'history', 'photo']::text[], 'always', null, 50, 75, 10, 6),
  ('chinatown-chin-park', 'place-chncl', 'scenic', 'Find a Quiet Corner at Chin Park', 'Just beyond the Chinatown gate, find the bamboo and pick a place where you’d pause before heading back to the T. Best in daylight.', 42.3512, -71.05815, 0, array['park', 'outdoors', 'quiet']::text[], 'always', null, 50, 75, 15, 7),
  ('chinatown-winsor-dim-sum', 'place-chncl', 'food', 'Pick a Dim Sum Plate', 'Visit Winsor Dim Sum Café at 10 Tyler Street. Compare the radish cakes with a dumpling plate and choose what to try.', 42.35117, -71.06061, 2, array['dim-sum', 'dumplings', 'sit-down']::text[], '10:00-20:00', null, 60, 75, 35, 4)
